namespace BeamScheduleFormatter {static class InputFocus {public static void Apply(Control root){foreach(Control c in root.Controls){var t=c as TextBox;var n=c as NumericUpDown;var combo=c as ComboBox;if((t!=null&&!t.ReadOnly)||n!=null||combo!=null){Color normal=c.BackColor;c.Enter+=(s,e)=>{c.BackColor=Color.FromArgb(232,245,255);};c.Leave+=(s,e)=>{c.BackColor=normal;};c.Cursor=Cursors.IBeam;if(n!=null)n.Enter+=(s,e)=>n.Select(0,n.Text.Length);}if(!(c is DataGridView))Apply(c);}}}static class GridAppearance {static readonly ConditionalWeakTable<DataGridView,object> applied=new ConditionalWeakTable<DataGridView,object>();public static void Apply(DataGridView g){object seen;if(applied.TryGetValue(g,out seen))return;applied.Add(g,new object());g.ColumnHeadersDefaultCellStyle.WrapMode=DataGridViewTriState.True;g.ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.AutoSize;g.CellBorderStyle=DataGridViewCellBorderStyle.Single;g.ColumnHeadersBorderStyle=DataGridViewHeaderBorderStyle.Single;g.RowHeadersBorderStyle=DataGridViewHeaderBorderStyle.Single;g.GridColor=Color.FromArgb(175,188,202);g.BorderStyle=BorderStyle.FixedSingle;g.EditMode=DataGridViewEditMode.EditOnEnter;g.CellClick+=(o,a)=>{if(a.RowIndex>=0&&a.ColumnIndex>=0&&!g.Rows[a.RowIndex].Cells[a.ColumnIndex].ReadOnly)g.BeginEdit(false);};g.CellPainting+=(s,e)=>{if(e.RowIndex<0||e.ColumnIndex<0||(e.State&DataGridViewElementStates.Selected)==0)return;e.CellStyle.SelectionBackColor=Color.FromArgb(218,239,240);e.CellStyle.SelectionForeColor=e.CellStyle.ForeColor.IsEmpty?Color.Black:e.CellStyle.ForeColor;e.Paint(e.ClipBounds,e.PaintParts&~DataGridViewPaintParts.Focus);if(g.ContainsFocus&&g.CurrentCell!=null&&g.CurrentCell.RowIndex==e.RowIndex&&g.CurrentCell.ColumnIndex==e.ColumnIndex&&!g.CurrentCell.ReadOnly){var r=e.CellBounds;r.Inflate(-1,-1);using(var pen=new Pen(PowTheme.Teal,2))e.Graphics.DrawRectangle(pen,r);}e.Handled=true;};}}}

